# Reclaims disk space by removing Rust debug build trees.
#
# Cargo debug builds keep full debug info + .pdb files for every
# artifact (and for every incremental rebuild), so after a few dev
# sessions target/debug typically weighs 5-10 GB per crate. Everything
# deleted here is regenerated by the next build; nothing tracked by
# git lives in target.
#
# Release trees are preserved: shell/target/release/game-shell.exe is
# the template embedded into the builder at compile time, and
# src-tauri/target/release holds the built installers.
#
# Usage:
#   powershell -NoProfile -ExecutionPolicy Bypass -File tools\clean-dev.ps1          # clean both crates
#   powershell -NoProfile -ExecutionPolicy Bypass -File tools\clean-dev.ps1 -All     # also delete release trees (adds ~3 GB; full rebuild afterwards)

param([switch]$All)

$ErrorActionPreference = "SilentlyContinue"

# Repo root = parent of tools/
$root = Split-Path -Parent $PSScriptRoot

$debugDirs = @(
    (Join-Path $root "src-tauri\target\debug"),
    (Join-Path $root "shell\target\debug")
)

$sizeOf = { param($dir)
    if (Test-Path $dir) {
        [math]::Round(((Get-ChildItem $dir -Recurse -File | Measure-Object Length -Sum).Sum / 1GB), 2)
    } else { 0 }
}

$freed = 0
foreach ($dir in $debugDirs) {
    if (Test-Path $dir) {
        $size = & $sizeOf $dir
        $freed += $size
        Remove-Item $dir -Recurse -Force
        Write-Host ("removed {0} ({1} GB)" -f $dir, $size)
    }
}

if ($All) {
    $releaseDirs = @(
        (Join-Path $root "src-tauri\target\release"),
        (Join-Path $root "shell\target\release")
    )
    foreach ($dir in $releaseDirs) {
        if (Test-Path $dir) {
            $size = & $sizeOf $dir
            $freed += $size
            Remove-Item $dir -Recurse -Force
            Write-Host ("removed {0} ({1} GB)" -f $dir, $size)
        }
    }
    Write-Host "`nnote: -All removed release trees too; rebuild the shell"
    Write-Host "(cargo build --release in shell/) before building the app."
}
else {
    Write-Host "`nnote: release trees kept. Use -All to also remove them."
}

Write-Host ("freed: {0} GB" -f [math]::Round($freed, 2))
